 CREATE OR REPLACE FUNCTION public.restitutionpaymentismatched(startdate character varying, enddate character varying, pagenumber bigint, pagesize bigint, v_ismatched boolean, searchcol character varying, searchval character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
  RETURNS TABLE(totalcount bigint, restitutionpaymentflatfileid uuid, filename character varying, createddate timestamp without time zone, modifieddate timestamp without time zone, insertedon timestamp without time zone, filstatus character varying, restitutionpaymentflatfilecontentid uuid, asofdate character varying, lockboxno character varying, vakaccountnumber character varying, firstname character varying, lastname character varying, addressline1 character varying, addressline2 character varying, city character varying, state character varying, zip character varying, customernumber character varying, checkno character varying, checkamt numeric, contentinsertedon timestamp without time zone, ismatched boolean, paymentno bigint, account character varying)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 v_searchkey character varying ;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 v_pageoffset int;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
 v_pagenumber int;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
 declare searchstring character varying(5000);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
         v_pagenumber := pagenumber-1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
         v_pageoffset = v_pagenumber * pagesize;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
         --v_searchkey:= searchkey;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
         --                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
         searchstring:= coalesce(searchstring,'');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
         /*if (searchkey!='' or searchkey!=null) then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
         searchstring:=  '  AND  lower(RPFF.filename)  like    '''  ||  LOWER(searchkey)  ||  '%'' ';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
         RAISE NOTICE 'v_searchkey:%', searchkey;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
         --searchstring:=  '  AND  (RPFF.filename)  =  '''' ';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
         end if; */                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
         if (v_ismatched::character varying!='' or v_ismatched::character varying!=null) then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
         if v_ismatched = true then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
         searchstring:=  '  AND  REPFFC.ismatched  =  '''||v_ismatched||'''  AND  (REPFFC.status!=''Approved'' and REPFFC.status!=''Pending'' or REPFFC.status is null) AND customernumber in (select restitutionno::character varying from intakeserreqrestitution where activeflag=1) ';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
         else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
         searchstring:=  '  AND  REPFFC.ismatched  =  '''||v_ismatched||'''  AND  (REPFFC.status!=''Approved'' and REPFFC.status!=''Pending'' or REPFFC.status is null)  ';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
         end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
         end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
         /*if (v_restitutionpaymentflatfilecontentid!='' or v_restitutionpaymentflatfilecontentid!=null) then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
         searchstring:=  '  AND  REPFFC.restitutionpaymentflatfilecontentid  =  '''||v_restitutionpaymentflatfilecontentid||'''  ';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
         end if; */                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
       /*  if(v_ismatched=false) then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
        searchstring:=  '  AND  REPFFC.status  is null ';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
        end if;*/                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
         IF(searchcol!='' AND searchval  !='' ) THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
           IF  (searchcol='vakaccountnumber') THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                searchstring:=  '  AND  REPFFC.vakaccountnumber  =  '''||searchval||'''  ';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
           END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
           IF  (searchcol='restitutionpaymentflatfilecontentid') THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                searchstring:=  '  AND  REPFFC.restitutionpaymentflatfilecontentid  =  '''||searchval||'''  ';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
           END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
           IF  (searchcol='filename') THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                searchstring:=  '  AND  lower(RPFF.filename)  like    '''  ||  LOWER(searchval)  ||  '%'' AND  REPFFC.ismatched  =  '''||v_ismatched||''' ';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
           END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
         END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
       /*  if ((startdate!='' or startdate!=null) and (enddate!='' or enddate!=null)) then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
         searchstring:=  '  AND  lower(RPFF.filename)  like    '''  ||  LOWER(searchkey)  ||  '%''';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
         end if; */                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
       raise notice 'searchstring%',searchstring;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
         Return Query                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
         execute                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
         'select count(1) OVER(), RPFF.restitutionpaymentflatfileid, RPFF.filename, RPFF.createddate, RPFF.modifieddate, RPFF.insertedon ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
         (SELECT ''Success''::character varying) as filestatus,REPFFC.restitutionpaymentflatfilecontentid , REPFFC.asofdate, REPFFC.lockboxno,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
         REPFFC.vakaccountnumber, REPFFC.firstname, REPFFC.lastname, REPFFC.addressline1, REPFFC.addressline2 , REPFFC.city, REPFFC.state, REPFFC.zip,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
         REPFFC.customernumber, REPFFC.checkno, REPFFC.checkamt, REPFFC.insertedon, REPFFC.ismatched,REPFFC.paymentno ,(SELECT ''Restitution''::character varying) as account                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
         from restitutionpaymentflatfile as RPFF                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
         INNER JOIN restitutionpaymentflatfilecontent REPFFC                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
               ON  RPFF.restitutionpaymentflatfileid = REPFFC.restitutionpaymentflatfileid and REPFFC.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
         where REPFFC.asofdate!='''' and RPFF.activeflag = 1  '|| searchstring ||'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
         order by REPFFC.updatedon desc LIMIT '|| pagesize ||' OFFSET '|| v_pageoffset ||'';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
   end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    

